import 'server-only';

import { randomUUID } from 'node:crypto';

import type { StoragePrefix } from './types';

/**
 * Storage keys, generated by the server.
 *
 * `SECURITY.md` section 6: "Never used as a storage key. The key is a generated
 * UUID plus a derived extension." Section 7 adds that keys are unguessable and
 * **never returned to a client** — a client holds an opaque `DesignFile.id` and
 * asks for access.
 *
 * Three properties, each load-bearing:
 *
 *   - **Collision resistant.** A v4 UUID, and the column is unique, so a
 *     collision is a failed insert rather than an overwritten file.
 *   - **Unpredictable.** Guessing a key is guessing a UUID, and even then the
 *     bucket is private and every read is authorised first.
 *   - **Traversal-proof by construction.** Nothing user-supplied reaches a key.
 *     The extension comes from the *detected* type, from a fixed allowlist, so
 *     `../../etc/passwd` and `logo.svg.php` are not expressible here.
 */

const PREFIXES: Record<StoragePrefix, string> = {
  quarantine: 'quarantine',
  designs: 'designs',
  previews: 'previews',
  media: 'media',
  models: 'models',
};

/** Guards against a caller assembling a key from anything but this module. */
const KEY_PATTERN =
  /^(?:quarantine|designs|previews|media|models)\/[0-9a-f-]{36}(?:\.[a-z0-9]{2,5})?$/;

export function isValidStorageKey(key: string): boolean {
  return KEY_PATTERN.test(key);
}

/**
 * A fresh key for an upload.
 *
 * The same UUID follows the object from `quarantine/` to `designs/`, so
 * promotion is a rename rather than a new identity, and a log line about a
 * quarantined object still identifies the file it became.
 */
export function newObjectId(): string {
  return randomUUID();
}

export function storageKeyFor(input: {
  prefix: StoragePrefix;
  objectId: string;
  extension: string;
}): string {
  /**
   * The extension is cleaned and then *checked*, not merely cleaned.
   *
   * Callers pass one from the allowlist, so this never fires in practice. It
   * exists because a key this function can emit but `isValidStorageKey` would
   * reject is a key the adapter refuses to write — a failure at the storage
   * layer for a reason nobody can see. Anything unrecognisable is dropped, and
   * an extensionless key is perfectly valid: the type is in the database.
   */
  const cleaned = input.extension.toLowerCase().replace(/[^a-z0-9]/g, '');
  const suffix = /^[a-z0-9]{2,5}$/.test(cleaned) ? `.${cleaned}` : '';

  return `${PREFIXES[input.prefix]}/${input.objectId}${suffix}`;
}

/** The `designs/` key an object in quarantine is promoted to. */
export function promotedKey(quarantineKey: string): string {
  return quarantineKey.replace(/^quarantine\//, `${PREFIXES.designs}/`);
}

/**
 * A key for a shop photograph.
 *
 * The same shape as every other key — a generated UUID and a derived extension
 * — for the same reason: nothing the uploader supplied reaches it, so a file
 * called `../../.env` is not expressible. It differs only in being *public*,
 * which is a property of the prefix and of the bucket policy, never of the key.
 */
export function mediaKeyFor(objectId: string, extension: string): string {
  return storageKeyFor({ prefix: 'media', objectId, extension });
}

/**
 * A key for a garment model.
 *
 * Public like a photograph and generated like every other key. The extension is
 * always `glb` because that is the only container accepted (`domain/model3d`),
 * and it is stated rather than derived: a model is not published until it has
 * been parsed, so by the time a key is minted the type is a fact.
 */
export function modelKeyFor(objectId: string): string {
  return storageKeyFor({ prefix: 'models', objectId, extension: 'glb' });
}

/** True for the two prefixes served without a signature. */
export function isPublicMediaKey(key: string): boolean {
  return isValidStorageKey(key) && key.startsWith(`${PREFIXES.media}/`);
}

export function isPublicModelKey(key: string): boolean {
  return isValidStorageKey(key) && key.startsWith(`${PREFIXES.models}/`);
}

/**
 * Anything the public asset route may serve, and what it is.
 *
 * One function so the route has one whitelist rather than a chain of `if`s that
 * a third public prefix could be added to without anybody noticing. Returning
 * the content type from the same place that grants access is deliberate: the
 * decision "this may be served" and the decision "as this type" are made
 * together, and the route never guesses.
 */
export function publicContentTypeFor(key: string): string | null {
  if (isPublicMediaKey(key)) return 'image/jpeg';
  if (isPublicModelKey(key)) return 'model/gltf-binary';

  return null;
}

/** Previews are generated rasters, stored beside the file they describe. */
export function previewKeyFor(objectId: string): string {
  return storageKeyFor({ prefix: 'previews', objectId, extension: 'jpg' });
}
